// ============================================
// CLASIFICACIÓN DE INTENT Y PLANTILLA
// ============================================

const events = $input.all();
const responses = [];

for (const event of events) {
  const payload = event.json.payload;
  const email = payload.data?.email;
  const subject = payload.data?.subject || '';
  const intent = payload.data?.intent || 'general_inquiry';
  const businessName = payload.data?.business_name || '';

  if (!email) continue;

  // Seleccionar plantilla según intent
  let emailSubject = '';
  let emailBody = '';

  if (intent === 'demo_request') {
    emailSubject = '🚀 Tu demo de SmarterOS está lista';
    emailBody = `Hola ${businessName || 'equipo'},

¡Gracias por tu interés en SmarterOS!

Vimos que quieres una demo de nuestro CRM con automatización.

📅 **Opciones:**

1. **Demo Guiada (15 min)** → Agenda aquí: https://cal.com/smarterbot/demo
2. **Demo Auto-guiada** → Video de 5 min: https://loom.com/smarteros-demo
3. **Activación Directa** → Respondé este email y lo activamos ya

💰 **Plan recomendado: PRO**
- CRM con Odoo incluido
- Automatización de ventas
- Integración con email, WhatsApp, web
- $150.000/mes

¿Cuál opción preferís?

—
Equipo SmarterOS
https://smarterbot.store`;
  }
  else if (intent === 'pricing_request') {
    emailSubject = '💰 Propuesta SmarterOS - Automatización B2B';
    emailBody = `Hola ${businessName || 'equipo'},

Gracias por consultar por nuestros planes!

📊 **Nuestros Planes:**

┌─────────────────────────────────────────┐
│ BÁSICO - $50.000/mes                    │
├─────────────────────────────────────────┤
│ • Captura de leads (web + email)        │
│ • Validación automática                 │
│ • Registro en PostgreSQL                │
│ • Soporte básico                        │
└─────────────────────────────────────────┘

┌─────────────────────────────────────────┐
│ PRO - $150.000/mes ⭐ RECOMENDADO       │
├─────────────────────────────────────────┤
│ • Todo lo del Básico +                  │
│ • CRM en Odoo                           │
│ • Scoring de leads                      │
│ • Pipeline de ventas                    │
│ • Integración WhatsApp                  │
└─────────────────────────────────────────┘

┌─────────────────────────────────────────┐
│ ENTERPRISE - $300.000/mes               │
├─────────────────────────────────────────┤
│ • Todo lo del Pro +                     │
│ • DTE automático (facturación)          │
│ • Onboarding con Picoclaw               │
│ • Auto-learning                         │
│ • Analytics avanzado                    │
│ • Soporte prioritario 24/7              │
└─────────────────────────────────────────┘

🎯 **¿Cuál se ajusta más a tu necesidad?**

Respondé este email y te ayudo a activarlo.

—
Equipo SmarterOS
https://smarterbot.store`;
  }
  else if (intent === 'enterprise_inquiry') {
    emailSubject = '🏢 SmarterOS Enterprise - Contacto Directo';
    emailBody = `Hola ${businessName || 'equipo'},

¡Excelente! Veo que estás interesado en nuestra solución Enterprise.

🎯 **Para empresas que buscan:**
- Automatización completa
- Facturación electrónica (DTE)
- Múltiples canales (web, email, WhatsApp, Telegram)
- Analytics en tiempo real
- Soporte prioritario

💼 **Plan Enterprise: $300.000/mes**

Incluye:
- Todo lo del Plan Pro
- DTE automático (SII)
- Onboarding personalizado
- Auto-learning (mejora continua)
- Dashboard analytics
- Soporte 24/7

📞 **¿Agendamos una llamada de 15 min?**

Calendario: https://cal.com/smarterbot/enterprise

O respondé este email con tu horario preferido.

—
Equipo SmarterOS
https://smarterbot.store`;
  }
  else {
    emailSubject = '👋 Gracias por contactar SmarterOS';
    emailBody = `Hola ${businessName || 'equipo'},

¡Gracias por tu mensaje!

🤖 **SmarterOS** es tu asistente de automatización B2B.

📌 **Te ayudo con:**
- Captura automática de leads
- CRM con Odoo
- Automatización de ventas
- Integración con email, WhatsApp, web
- Facturación electrónica (DTE)

💬 **¿En qué puedo ayudarte?**

Respondé este email y te asisto.

—
Equipo SmarterOS
https://smarterbot.store`;
  }

  responses.push({
    json: {
      event_id: event.json.id,
      to: email,
      subject: emailSubject,
      body: emailBody,
      intent: intent
    }
  });
}

return responses;
